// Dashboard numbers, always counted from stored records (never generated by the AI).
import { query } from "@/lib/db.ts";

export type OverviewCounts = {
  newOpportunities: number;
  unread: number;
  highPriority: number;
  needsReply: number;
  dueThisWeek: number;
  draftsToReview: number;
  awaitingThem: number;
  needsReview: number;
};

const OPEN_STATUSES = `('new','reviewed','interested','needs_information','reply_drafted',
  'awaiting_my_response','awaiting_their_response','in_negotiation','confirmed','accepted')`;

export async function getOverviewCounts(): Promise<OverviewCounts> {
  const rows = await query<Record<keyof OverviewCounts, string>>(`
    SELECT
      count(*) FILTER (WHERE status = 'new')                                              AS "newOpportunities",
      count(*) FILTER (WHERE NOT is_read)                                                 AS "unread",
      count(*) FILTER (WHERE priority = 'high' AND status IN ${OPEN_STATUSES})            AS "highPriority",
      count(*) FILTER (WHERE status IN ('new','awaiting_my_response','needs_information')) AS "needsReply",
      count(*) FILTER (WHERE status IN ${OPEN_STATUSES}
                         AND next_deadline_at BETWEEN now() AND now() + interval '7 days') AS "dueThisWeek",
      (SELECT count(*) FROM drafts WHERE status IN ('ready','saved_to_gmail'))            AS "draftsToReview",
      count(*) FILTER (WHERE status = 'awaiting_their_response')                          AS "awaitingThem",
      count(*) FILTER (WHERE priority = 'needs_review' AND status = 'new')
        + (SELECT count(*) FROM emails WHERE processing_state = 'needs_review')          AS "needsReview"
    FROM opportunities
    WHERE NOT is_irrelevant AND (snoozed_until IS NULL OR snoozed_until < now())
  `);
  const r = rows[0];
  const n = (v: string | undefined) => Number(v ?? 0);
  return {
    newOpportunities: n(r?.newOpportunities),
    unread: n(r?.unread),
    highPriority: n(r?.highPriority),
    needsReply: n(r?.needsReply),
    dueThisWeek: n(r?.dueThisWeek),
    draftsToReview: n(r?.draftsToReview),
    awaitingThem: n(r?.awaitingThem),
    needsReview: n(r?.needsReview),
  };
}

export type FlaggedItem = {
  id: string;
  title: string;
  organization: string | null;
  flagged_for_talent_at: Date;
  talent_response: "interested" | "pass" | "questions" | null;
  talent_response_note: string | null;
  talent_responded_at: Date | null;
};

/** Offers put to her in the last two weeks: unanswered first, then her latest answers. */
export async function listFlagged(): Promise<{ items: FlaggedItem[]; talentEmail: string | null }> {
  const [items, talent] = await Promise.all([
    query<FlaggedItem>(
      `SELECT id, title, organization, flagged_for_talent_at, talent_response, talent_response_note, talent_responded_at
       FROM opportunities
       WHERE flagged_for_talent_at > now() - interval '14 days' AND NOT is_irrelevant
         AND status NOT IN ('declined', 'completed', 'expired', 'archived')
       ORDER BY (talent_response IS NULL) DESC, COALESCE(talent_responded_at, flagged_for_talent_at) DESC
       LIMIT 6`,
    ),
    query<{ value: unknown }>(`SELECT value FROM preferences WHERE key = 'talent_email'`),
  ]);
  return { items, talentEmail: typeof talent[0]?.value === "string" ? (talent[0].value as string) : null };
}

export type RunwayMark = { id: string; title: string; organization: string | null; kind: "reply" | "event"; at: Date };

/** The next 14 days: reply-by dates and shoots or events of open, unsnoozed offers. */
export async function listRunway(days = 14): Promise<RunwayMark[]> {
  return query<RunwayMark>(
    `SELECT id, title, organization, kind, at FROM (
       SELECT id, title, organization, 'reply' AS kind, reply_by_at AS at, status, is_irrelevant, snoozed_until FROM opportunities
       UNION ALL
       SELECT id, title, organization, 'event' AS kind, event_start_at AS at, status, is_irrelevant, snoozed_until FROM opportunities
     ) d
     WHERE at IS NOT NULL
       AND at >= date_trunc('day', now() AT TIME ZONE 'Asia/Kolkata') AT TIME ZONE 'Asia/Kolkata'
       AND at < (date_trunc('day', now() AT TIME ZONE 'Asia/Kolkata') + make_interval(days => $1)) AT TIME ZONE 'Asia/Kolkata'
       AND NOT is_irrelevant AND (snoozed_until IS NULL OR snoozed_until < now())
       AND status NOT IN ('declined', 'completed', 'expired', 'archived')
       AND NOT (kind = 'reply' AND status IN ('confirmed', 'accepted', 'awaiting_their_response'))
     ORDER BY at
     LIMIT 60`,
    [days],
  );
}

export type MapPoint = {
  id: string;
  title: string;
  organization: string | null;
  priority: "high" | "medium" | "low" | "needs_review";
  next_deadline_at: Date | null;
  compensation_type: string;
  compensation_status: string;
  amount_min: string | null;
  amount_max: string | null;
  currency: string;
};

/** Every open offer, for the map. */
export async function listMapPoints(): Promise<MapPoint[]> {
  return query<MapPoint>(
    `SELECT id, title, organization, priority, next_deadline_at, compensation_type, compensation_status, amount_min, amount_max, currency
     FROM opportunities
     WHERE NOT is_irrelevant AND status NOT IN ('declined', 'completed', 'expired', 'archived')
     ORDER BY CASE priority WHEN 'high' THEN 0 WHEN 'needs_review' THEN 1 WHEN 'medium' THEN 2 ELSE 3 END, last_activity_at DESC
     LIMIT 60`,
  );
}
